package com.example.controlstatement;

public class Break {
	
	public static void num() {
		for(int a= 0; a < 17; a++) {
			System.out.println(a);
			if(a == 9 )
				break;
		}
		
		System.out.println("fdjgg");
	}

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		num();
	}

}
